thm-hyp(
    Topology.T4(S@Topology.ctxt.S),
    Logic.forall-typed(
        @E, 
        Set(S@Topology.ctxt.S),
        Logic.forall-typed(
            @F, 
            Set(S@Topology.ctxt.S),
            Logic.implies(
                Logic.and(Logic.and(
                    Topology.closedSet[text](E, τ@Topology.ctxt.tau, S@Topology.ctxt.S), Topology.closedSet[text](F, τ@Topology.ctxt.tau, S@Topology.ctxt.S)
                ), Eq(Set.inter(E, F), Set.emptyset)),
                Logic.exists-typed(
                    @f, 
                    Topology.cont(S@Topology.ctxt.S, Real), 
                    Logic.and(
                        Logic.forall-typed(
                            @x, 
                            E,
                            Eq(Type.apply(f, x), 0)
                        ), 
                        Logic.forall-typed(
                            @x, 
                            F,
                            Eq(Type.apply(f, x), 1)
                        ), 
                    )
                )
            )
        )
    )
)
